using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;

using System.Windows.Forms;
using MC2Pack;
namespace Astera {
sealed partial class LibraryForm {
    internal static int AuditLibraryIconStartup(string root){try{
        if(Directory.Exists(root))throw new IOException("Use a fresh icon startup audit");Directory.CreateDirectory(root);var checks=new List<string>();
        var png=Path.Combine(root,"icon.png");using(var b=new Bitmap(32,32)){using(var g=Graphics.FromImage(b))g.Clear(Color.Gold);b.Save(png);}
        string gif=Path.Combine(root,"icon.gif");File.WriteAllBytes(gif,Convert.FromBase64String("R0lGODlhEAAQAIEAAP8AAAAAAAAAAAAAACH/C05FVFNDQVBFMi4wAwEAAAAh+QQACgAAACwAAAAAEAAQAAAIHQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFgQEBACH5BAEKAAEALAAAAAAQABAAgQAA/wAAAAAAAAAAAAgdAAEIHEiwoMGDCBMqXMiwocOHECNKnEixosWBAQEAOw=="));
        var state=new Store(Path.Combine(root,"state"));state.Settings.CheckOnStart=false;state.Settings.UseMinecraftSkin=false;state.Settings.KeepInTray=false;
        string steamapps=Path.Combine(root,"Steam","steamapps"),steamFolder=Path.Combine(steamapps,"common","Steam Fixture");Directory.CreateDirectory(steamFolder);File.WriteAllText(Path.Combine(steamapps,"appmanifest_42.acf"),"\"AppState\" { \"appid\" \"42\" \"installdir\" \"Steam Fixture\" \"name\" \"Steam Fixture\" }");string steamCache=Path.Combine(state.Root,"artwork","steam");Directory.CreateDirectory(steamCache);File.Copy(png,Path.Combine(steamCache,"42-portrait.png"));
        string itchFolder=Path.Combine(root,"itch-game");Directory.CreateDirectory(Path.Combine(itchFolder,".itch"));File.WriteAllText(Path.Combine(itchFolder,".itch","receipt.json"),"{\"game\":{\"id\":789,\"title\":\"Itch Fixture\",\"cover_url\":\"https://img.itch.zone/fixture.gif\"}}");string itchCache=Path.Combine(state.Root,"artwork","itch");Directory.CreateDirectory(itchCache);File.Copy(gif,ItchArtwork.Cached(itchCache,ItchMetadata.Read(itchFolder)));
        string robloxCache=Path.Combine(state.Root,"artwork","roblox");Directory.CreateDirectory(robloxCache);File.Copy(png,Path.Combine(robloxCache,"rbx-13058-icon.png"));
        var fixtures=new[]{new CustomGame{Name="00 Custom PNG",Executable=Path.Combine(root,"absent.exe"),Icon=png},new CustomGame{Name="01 Custom GIF",Executable=Path.Combine(root,"absent.exe"),Icon=gif},new CustomGame{Name="02 Steam cached portrait",Executable=steamFolder,Platform="steam",PlatformId="42"},new CustomGame{Name="03 Itch cached GIF",Executable=itchFolder,Platform="itch",PlatformId="789"},new CustomGame{Name="04 Roblox cached icon",Executable=RobloxSupport.WebUrl(1818),Platform="roblox",PlatformId="1818",UniverseId=13058},new CustomGame{Name="05 EXE icon",Executable=Application.ExecutablePath}};
        state.Settings.CustomGames.AddRange(fixtures);for(int i=6;i<35;i++)state.Settings.CustomGames.Add(new CustomGame{Name=i.ToString("00")+" Scrolled game",Executable=Path.Combine(root,"absent.exe"),Icon=png});
        using(var form=new LibraryForm(state,new Channel(),true))using(var clock=new Timer{Interval=50}){
            form.TopMost=true;form.StartPosition=FormStartPosition.Manual;form.Location=Screen.PrimaryScreen.WorkingArea.Location;form.libraryScrollbar.MoveTo(0);int ticks=0,stage=0,code=1;string originalNotes=null;Image originalIcon=null;
            clock.Tick+=delegate{try{if(++ticks>150)throw new IOException("Icon startup audit timed out");
                if(stage==0){if(!fixtures.All(g=>form.CustomLibraryIcon(g)!=null))return;AuditAssert(form.GameKind==0&&form.notes.Text==originalNotes,"Icon preloading changed the selected game or notes");checks.Add("Visible custom PNG/GIF, Steam cache, itch GIF cache, Roblox cache and EXE icons load without selecting their games or using the network");AuditAssert(form.AnimatedLibraryIcon(fixtures[1])!=null&&form.AnimatedLibraryIcon(fixtures[3])!=null,"Preloaded GIF icons were not registered for playback");checks.Add("Unselected custom and itch GIFs retain animation after cache-first loading");form.CaptureVisibleUi(root,"startup-visible-icons");originalIcon=form.VisibleLibraryIcon(fixtures[0]);form.WarmVisibleLibraryIcons(false);AuditAssert(ReferenceEquals(originalIcon,form.VisibleLibraryIcon(fixtures[0])),"Unchanged viewport recreated icon objects");checks.Add("Repeated viewport notifications retain the existing icon objects");var stale=new CustomGame{Id=fixtures[0].Id,Executable=fixtures[0].Executable,Icon=fixtures[0].Icon};string key=LibraryIconKey(stale);fixtures[0].Icon=gif;using(var result=ReadLibraryIcon(png))AuditAssert(!form.ApplyLibraryIcon(stale,key,result),"Late icon replaced changed custom artwork");fixtures[0].Icon=png;checks.Add("Late icon results cannot replace an edited game link or changed artwork");fixtures[1].Icon="";using(var fallback=new LibraryIconResult{Image=new Bitmap(16,16)})AuditAssert(form.ApplyLibraryIcon(fixtures[1],LibraryIconKey(fixtures[1]),fallback)&&form.VisibleLibraryIconPath(fixtures[1])==null&&form.AnimatedLibraryIcon(fixtures[1])==null,"Removing a GIF retained its old animated path");checks.Add("Clearing custom GIF artwork releases its displayed animation when an EXE fallback replaces it");form.libraryScrollbar.MoveTo(form.libraryScrollbar.Maximum);form.WarmVisibleLibraryIcons(false);stage=1;return;}
                if(stage==1){var last=state.Settings.CustomGames.Last();if(form.CustomLibraryIcon(last)==null)return;AuditAssert(form.GameKind==0,"Scrolling icons changed selection");checks.Add("Scrolling hydrates newly visible rows without selecting or launching a game");form.librarySearch.Text="02 Steam";form.WarmVisibleLibraryIcons(false);AuditAssert(form.games.Items.Count==1&&form.CustomLibraryIcon(fixtures[2])!=null,"Search lost a cached library icon");checks.Add("Search results reuse loaded icons without waiting for a game selection");File.WriteAllText(Path.Combine(root,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,GamesExecuted=false,LivePreferencesChanged=false,NetworkUsed=false}));code=0;clock.Stop();form.Close();}
            }catch(Exception error){clock.Stop();File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());form.Close();}};
            form.Shown+=delegate{form.libraryScrollbar.MoveTo(0);originalNotes=form.notes.Text;form.WarmVisibleLibraryIcons(false);clock.Start();};Application.Run(form);return code;
        }
    }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
}
}
